import * as legacy from './legacy/dgn-traits.js';
import { hasDegeneretteWilds } from '../chain/schema.js';
// /app/app/dgn-traits.js — shared Degenerette trait codecs.
//
// Single source of truth for the badge-path / ticket-unpack / match-compare
// trio. Previously module-private in app-degenerette-panel.js; extracted so
// the reveal overlay (box-spin reels) renders tickets with the SAME decode.
// Duplicated decoders are how the color/symbol bit-swap bug (f47f106) shipped
// — do not copy these tables into another file.
//
// Global trait IDs (ordinary jackpot tickets, foil traits) are one byte per
// quadrant: [QQ: bits 6-7 quadrant | CCC: bits 3-5 color | SSS: bits 0-2 symbol].
// Degenerette tickets are a separate format, one lane byte per quadrant (byte
// position = quadrant, LSB-first): [0 | W: bit 6 wild | CCC | SSS]. A wild lane
// is 0x40 | symbol with zero color bits; dgnUnpackTicket decodes it as
// {sym, col: null, wild: true}. Only dgnUnpackTicket and the Degenerette
// helpers below read lane bytes; dgnTraitIdToQSC and the ticket accent keep the
// global layout.

import { resolveBadgeUrl } from './badge-sprite.js';
import { GOLD_SIX_MONKEY_BADGE, isGoldSix } from './gold-six.js';

export const DGN_QUADRANTS = ['crypto', 'zodiac', 'cards', 'dice'];

export const DGN_SYMBOLS = Object.freeze({
  crypto: ['xrp', 'tron', 'sui', 'monero', 'solana', 'chainlink', 'ethereum', 'bitcoin'],
  zodiac: ['aries', 'taurus', 'gemini', 'cancer', 'leo', 'libra', 'sagittarius', 'aquarius'],
  cards:  ['club', 'diamond', 'heart', 'spade', 'horseshoe', 'cashsack', 'king', 'ace'],
  dice:   ['1', '2', '3', '4', '5', '6', '7', '8'],
});

// The 'cards' quadrant remaps symbol → SVG file index (legacy filename order).
// Load-bearing — do not simplify.
export const DGN_CARD_IDX = [3, 4, 5, 6, 0, 2, 1, 7];

export const DGN_COLORS = ['pink', 'purple', 'green', 'red', 'blue', 'orange', 'silver', 'gold'];

/** Player-facing symbol name; asset slugs remain unchanged. */
export function dgnDisplaySymbol(q, sym, col) {
  const category = DGN_QUADRANTS[Number(q)];
  const symbol = DGN_SYMBOLS[category]?.[Number(sym)];
  const color = col == null ? null : typeof col === 'string' ? col : DGN_COLORS[Number(col)];
  if (category === 'crypto' && Number(sym) === 0) return 'wwxrp';
  return category === 'dice' && Number(sym) === 5 && color === 'gold'
    ? '6ix'
    : symbol;
}

// Wild lanes carry no color; they render on the neutral ring with a WILD tag.
export const DGN_WILD_HEX = '#e6e6f0';
const DGN_WILD_RING_COLOR = 6;

export const DGN_COLOR_HEX = Object.freeze({
  // Exact outer-ring fills from /badges-circular/*.svg. These are deliberately
  // not theme approximations: the picker dot should be the badge it selects.
  pink: '#f409cd', purple: '#7c2bff', green: '#30d100', red: '#ed0e11',
  blue: '#1317f7', orange: '#f7931a', silver: '#5e5e5e', gold: '#ab8d3f',
});

/** Give a rendered trait cell the exact palette of its circular badge. */
export function applyDgnTraitColor(element, col) {
  const name = col == null ? 'wild' : typeof col === 'string' ? col : DGN_COLORS[Number(col)];
  const hex = col == null ? DGN_WILD_HEX : DGN_COLOR_HEX[name];
  if (!element || !hex) return null;
  try {
    if (typeof element.style?.setProperty === 'function') {
      element.style.setProperty('--dgn-trait-color', hex);
    } else if (element.style) {
      element.style['--dgn-trait-color'] = hex;
    }
  } catch (_e) { /* visual enhancement only */ }
  try { element.setAttribute?.('data-trait-color', name); } catch (_e) {}
  return Object.freeze({ name, hex });
}

// Ticket paper uses the trait palette for its three structural strokes: outer
// edge, cross dividers, and centre-diamond edge. Gold is deliberately brighter
// than the badge's antique-gold outer ring so it still reads against paper.
const DGN_TICKET_ACCENT_HEX = Object.freeze([
  '#f409cd', '#7c2bff', '#30d100', '#ed0e11',
  '#1317f7', '#f7931a', '#7b8490', '#d4af37',
]);

/**
 * Stable ticket-specific line colour.
 *
 * A gold trait always makes the ticket gold. Otherwise FNV-1a over the four
 * canonical trait bytes chooses only among non-gold colours absent from the
 * ticket. The result therefore feels varied without changing between renders.
 * Accepts either stored trait IDs or quadrant objects ({sym,col}/{s,c}).
 */
export function dgnTicketAccent(traits = []) {
  const bytes = new Array(4).fill(0xFF);
  const usedColors = new Set();
  for (const [index, raw] of (Array.isArray(traits) ? traits : []).entries()) {
    if (raw == null) continue;
    if (typeof raw === 'number' || typeof raw === 'bigint') {
      const byte = Number(raw) & 0xFF;
      const q = (byte >> 6) & 3;
      const col = (byte >> 3) & 7;
      bytes[q] = byte;
      usedColors.add(col);
      continue;
    }
    if (typeof raw !== 'object') continue;
    const q = Number(raw.q ?? raw.quadrant ?? index) & 3;
    const sym = Number(raw.sym ?? raw.s);
    const col = Number(raw.col ?? raw.c);
    if (!Number.isInteger(sym) || !Number.isInteger(col)) continue;
    const normalizedCol = col & 7;
    bytes[q] = ((q & 3) << 6) | (normalizedCol << 3) | (sym & 7);
    usedColors.add(normalizedCol);
  }

  let colorIndex = 7;
  if (!usedColors.has(7)) {
    const available = Array.from({ length: 7 }, (_unused, index) => index)
      .filter((index) => !usedColors.has(index));
    let hash = 0x811C9DC5;
    for (const byte of bytes) {
      hash ^= byte;
      hash = Math.imul(hash, 0x01000193);
    }
    colorIndex = available[(hash >>> 0) % available.length];
  }
  return Object.freeze({
    index: colorIndex,
    name: DGN_COLORS[colorIndex],
    hex: DGN_TICKET_ACCENT_HEX[colorIndex],
  });
}

/** Apply the stable accent without making every renderer know CSS details. */
export function applyDgnTicketAccent(element, traits = []) {
  if (!element) return dgnTicketAccent(traits);
  const accent = dgnTicketAccent(traits);
  try {
    if (typeof element.style?.setProperty === 'function') {
      element.style.setProperty('--ticket-line-color', accent.hex);
    } else if (element.style) {
      element.style['--ticket-line-color'] = accent.hex;
    }
  } catch (_e) { /* visual enhancement only */ }
  try { element.setAttribute?.('data-ticket-accent', accent.name); } catch (_e) {}
  return accent;
}

/** Inventory card click → load its four traits into the Degenerette builder. */
export const DGN_TICKET_COPY_EVENT = 'degenerette:copy-ticket';

/** Badge SVG path for (quadrant, symbol, color) — /badges-circular/ set. A null color (a wild lane) uses the neutral ring. */
export function dgnBadgePath(q, sym, col) {
  const cat = DGN_QUADRANTS[q];
  const fileIdx = cat === 'cards' ? DGN_CARD_IDX[sym] : sym;
  const color = DGN_COLORS[col ?? DGN_WILD_RING_COLOR];
  return resolveBadgeUrl(`/badges-circular/${cat}_${String(fileIdx).padStart(2, '0')}_${DGN_SYMBOLS[cat][sym]}_${color}.svg`);
}

/** Actual issued jackpot entries only; never use for drafts, reels or deity art. */
export function issuedTicketBadgePath(q, sym, col) {
  return isGoldSix(q, sym, col) ? GOLD_SIX_MONKEY_BADGE : dgnBadgePath(q, sym, col);
}

/** Standalone trait mark without the ticket badge's color/black/white rings. */
export function dgnSymbolPath(q, sym, col) {
  const cat = DGN_QUADRANTS[q];
  const fileIdx = cat === 'cards' ? DGN_CARD_IDX[sym] : sym;
  const color = DGN_COLORS[col ?? DGN_WILD_RING_COLOR];
  return resolveBadgeUrl(`/symbols/${cat}_${String(fileIdx).padStart(2, '0')}_${DGN_SYMBOLS[cat][sym]}_${color}.svg`);
}

/** Display name of a lane color: the color, or WILD for a wild lane. */
export function dgnColorName(col) {
  return col == null ? 'wild' : DGN_COLORS[Number(col)];
}

/**
 * Degenerette uint32 ticket (playerTraits / resultTraits) → 4 × {sym, col,
 * wild}; lane q is byte q (LSB-first). A wild lane (bit 6) has col null.
 */
function wild_dgnUnpackTicket(packed) {
  let p = 0n;
  try { p = BigInt(packed ?? 0); } catch (_e) { p = 0n; }
  const out = [];
  for (let q = 0; q < 4; q++) {
    const b = Number((p >> BigInt(q * 8)) & 0xFFn);
    const wild = (b & 0x40) !== 0;
    out.push({ sym: b & 7, col: wild ? null : (b >> 3) & 7, wild });
  }
  return out;
}

/** The quadrant of a Degenerette player ticket's wild (hero) lane, or null when it has none. */
export function dgnHeroQuadrant(packed) {
  const lanes = dgnUnpackTicket(packed);
  const q = lanes.findIndex((lane) => lane.wild);
  return q < 0 ? null : q;
}

/** Whether a Degenerette lane pair's colors score: equal colors, or either lane wild. */
export function dgnColorMatches(player, house) {
  return Boolean(player?.wild || house?.wild) || player?.col === house?.col;
}

/** Paint a Degenerette lane cell: its color ring, or the WILD tag for a wild lane. */
export function applyDgnLane(cell, lane) {
  applyDgnTraitColor(cell, lane?.col ?? null);
  try { cell?.classList?.toggle('is-wild', Boolean(lane?.wild)); } catch (_e) { /* visual only */ }
}

/**
 * A stored trait_id (0-255, the indexer's `traits_generated.traitId`) → its
 * quadrant/symbol/color. Same bit layout as one byte of a packed ticket:
 * quadrant in bits 6-7, color in 3-5, symbol in 0-2.
 *
 * @param {number} tid
 * @returns {{q: number, sym: number, col: number}}
 */
export function dgnTraitIdToQSC(tid) {
  const t = Number(tid) & 0xFF;
  return { q: (t >> 6) & 3, sym: t & 7, col: (t >> 3) & 7 };
}

/**
 * Four trait_ids (one card's entries) → the `traits` array #buildTicket wants,
 * indexed BY QUADRANT. Entries whose trait has not rolled yet come through as
 * null, which renders an empty quadrant.
 *
 * @param {Array<number|null|undefined>} traitIds
 * @returns {Array<{sym: number, col: number} | null>}
 */
export function dgnTraitIdsToQuadrants(traitIds) {
  const out = [null, null, null, null];
  for (const tid of (Array.isArray(traitIds) ? traitIds : [])) {
    if (tid == null) continue;
    const { q, sym, col } = dgnTraitIdToQSC(tid);
    out[q] = { sym, col };
  }
  return out;
}

/**
 * Partition a chronological `/tickets/by-trait` payload into whole tickets and
 * standalone quarter-ticket entries. The API's four-entry buckets can straddle
 * independent generation calls when the first call ends fractionally.
 * Quadrant bits remain authoritative, so a Q0 restart identifies that boundary
 * without throwing away the unfinished, economically real entries.
 *
 * Each returned record includes a stable key. Ordinary aligned API cards keep
 * their numeric cardIndex for backward-compatible reveal tracking; repaired
 * tickets spanning buckets use their constituent entry IDs.
 */
export function dgnPartitionTicketEntries(cards) {
  const orderedCards = Array.isArray(cards) ? [...cards] : [];
  orderedCards.sort((a, b) => Number(a?.cardIndex ?? 0) - Number(b?.cardIndex ?? 0));

  const tickets = [];
  const entries = [];
  let current = [];
  const looseKey = (row, ordinal) => {
    const entryId = Number(row?.entryId);
    if (Number.isFinite(entryId)) return `entry:${entryId}`;
    return `entry-card:${String(row?.rawCardIndex ?? 'unknown')}:${ordinal}:${row.traitId}`;
  };
  const flushLoose = () => {
    for (const row of current) {
      entries.push({
        traitId: row.traitId,
        entryId: row.entryId,
        cardIndex: row.rawCardIndex,
        key: looseKey(row, entries.length),
      });
    }
    current = [];
  };

  for (const card of orderedCards) {
    const cardEntries = Array.isArray(card?.entries) ? [...card.entries] : [];
    cardEntries.sort((a, b) => Number(a?.entryId ?? 0) - Number(b?.entryId ?? 0));
    for (const entry of cardEntries) {
      // Unrevealed entries arrive as traitId null, and Number(null) is 0 — the
      // valid trait for crypto/pink/XRP. Reject null before coercing or every
      // pending slot both paints as pink XRP and splits the ticket it sits in.
      const rawTid = entry?.traitId;
      const tid = rawTid == null ? NaN : Number(rawTid);
      if (!Number.isInteger(tid) || tid < 0 || tid > 255) {
        flushLoose();
        continue;
      }
      const { q } = dgnTraitIdToQSC(tid);

      // A new Q0 before Q3 is a fresh generation call. Its predecessor was a
      // legitimate fractional ticket, not the top half of this one.
      if (q === 0 && current.length > 0) flushLoose();
      if (q !== current.length) {
        flushLoose();
        if (q !== 0) {
          const row = {
            traitId: tid,
            entryId: entry?.entryId,
            rawCardIndex: card?.cardIndex,
          };
          entries.push({
            traitId: row.traitId,
            entryId: row.entryId,
            cardIndex: row.rawCardIndex,
            key: looseKey(row, entries.length),
          });
          continue;
        }
      }
      current.push({
        traitId: tid,
        entryId: entry?.entryId,
        rawCardIndex: card?.cardIndex,
      });
      if (current.length !== 4) continue;

      const rawIndexes = new Set(current.map((row) => String(row.rawCardIndex)));
      const rawCardIndex = rawIndexes.size === 1 ? current[0].rawCardIndex : null;
      const entryIds = current.map((row) => row.entryId);
      const hasEntryIds = entryIds.every((id) => id != null && Number.isFinite(Number(id)));
      tickets.push({
        traitIds: current.map((row) => row.traitId),
        key: rawCardIndex != null
          ? String(rawCardIndex)
          : hasEntryIds
            ? `entries:${entryIds.map(Number).join('.')}`
            : `traits:${current.map((row) => row.traitId).join('.')}:${tickets.length}`,
        entryIds,
        cardIndexes: [...new Set(current
          .map((row) => Number(row.rawCardIndex))
          .filter(Number.isFinite))],
      });
      current = [];
    }
  }
  flushLoose();
  return { tickets, entries };
}

/** Complete four-quadrant tickets, retained as the original public projection. */
export function dgnReconstructTicketRecords(cards) {
  return dgnPartitionTicketEntries(cards).tickets;
}

/** Canonical Q0..Q3 trait arrays for every reconstructed whole ticket. */
export function dgnReconstructTicketTraits(cards) {
  return dgnReconstructTicketRecords(cards).map((record) => record.traitIds);
}

/**
 * Per-lane compare on sym + color → 'full' | 'sym' | 'col' | 'miss'. A color
 * matches on equal colors or when either lane is wild. `wilds` counts the
 * house's wild lanes.
 */
function wild_dgnComputeMatches(player, house) {
  const states = [];
  let fullCount = 0;
  let wilds = 0;
  for (let q = 0; q < 4; q++) {
    const pt = player[q];
    const h = house[q];
    if (!pt || !h) { states.push('miss'); continue; }
    if (h.wild) wilds++;
    const symEq = pt.sym === h.sym;
    const colEq = dgnColorMatches(pt, h);
    if (symEq && colEq) { states.push('full'); fullCount++; }
    else if (symEq) states.push('sym');
    else if (colEq) states.push('col');
    else states.push('miss');
  }
  return { states, fullCount, wilds };
}

/** Visual states for Degenerette scoring: every state except 'miss' bears points. */
function wild_dgnScoringMatchStates(player, house) {
  return dgnComputeMatches(player, house).states;
}

export function dgnUnpackTicket(...args) { return (hasDegeneretteWilds() ? wild_dgnUnpackTicket : legacy.dgnUnpackTicket)(...args); }

export function dgnComputeMatches(...args) { return (hasDegeneretteWilds() ? wild_dgnComputeMatches : legacy.dgnComputeMatches)(...args); }

export function dgnScoringMatchStates(...args) { return (hasDegeneretteWilds() ? wild_dgnScoringMatchStates : legacy.dgnScoringMatchStates)(...args); }
